svg.script:
(function () {
  const root = document.documentElement;
  const n = 4;
  const bitCount = 2;
  const inputs = ['a', 'b', 'c', 'd'];
  const ys = [65, 100, 135, 170];
  let selection = 0;
  const el = (id) => document.getElementById(id);
  function render() {
    for (let i = 0; i < n; i++) {
      const active = i === selection;
      el('wire-' + i).setAttribute('class', active ? 'wire active' : 'wire');
      el('wire-' + i).setAttribute('marker-end', active ? 'url(#activeArrow)' : 'url(#arrow)');
      el('name-' + i).setAttribute('class', active ? 'name active' : 'name');
    }
    el('selected-route').setAttribute('d', 'M160 ' + ys[selection] + ' L405 117.5');
    el('output-wire').setAttribute('class','wire active');
    el('output-wire').setAttribute('marker-end','url(#activeArrow)');
    el('out-value').textContent = inputs[selection];
    el('selection-label').textContent = 'sel = ' + selection.toString(2).padStart(bitCount,'0') + ' → ' + inputs[selection];
    for (let bit = 0; bit < bitCount; bit++) {
      const on = !!(selection & (1 << bit));
      el('state-' + bit).textContent = on ? '1' : '0';
      el('switch-' + bit).setAttribute('class', on ? 'switch on' : 'switch');
      el('switch-' + bit).setAttribute('aria-pressed', on ? 'true' : 'false');
    }
  }
  for (let bit = 0; bit < bitCount; bit++) {
    const sw = el('switch-' + bit);
    const toggle = () => { selection ^= (1 << bit); render(); };
    sw.addEventListener('click', toggle);
    sw.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); toggle(); }
    });
  }
  render();
})();
